const $=s=>document.querySelector(s);
const T0=(()=>{const d=new Date();d.setHours(0,0,0,0);return d})();
const addD=(d,n)=>{const x=new Date(d);x.setDate(x.getDate()+n);return x};
const dd=(a,b)=>Math.round((new Date(b)-new Date(a))/864e5);
const dk=d=>d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');
const pdk=s=>{if(!s)return null;const[y,m,d]=String(s).slice(0,10).split('-').map(Number);return new Date(y,m-1,d)};
const fD=d=>{if(!d)return '—';d=typeof d==='string'&&/^\d{4}-\d\d-\d\d$/.test(d)?pdk(d):new Date(d);return d.toLocaleDateString('pt-BR')};
const fDT=d=>d?new Date(d).toLocaleString('pt-BR'):'—';
const BRL=v=>Number(v||0).toLocaleString('pt-BR',{style:'currency',currency:'BRL',maximumFractionDigits:0});
const BRL2=v=>Number(v||0).toLocaleString('pt-BR',{style:'currency',currency:'BRL'});
const N=(v,d=0)=>Number(v||0).toLocaleString('pt-BR',{minimumFractionDigits:d,maximumFractionDigits:d});
const P=(v,d=1)=>N(v,d)+'%';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const MESES=['jan','fev','mar','abr','mai','jun','jul','ago','set','out','nov','dez'];
const MESESL=['janeiro','fevereiro','março','abril','maio','junho','julho','agosto','setembro','outubro','novembro','dezembro'];
const DOW=['Domingo','Segunda','Terça','Quarta','Quinta','Sexta','Sábado'];
const compKey=d=>d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0');
const compLabel=k=>{const[y,m]=k.split('-').map(Number);return MESES[m-1]+'/'+y};
const kAdd=(k,n)=>{const[y,m]=k.split('-').map(Number);return compKey(new Date(y,m-1+n,1))};
const compOf=d=>d.getDate()>=21?compKey(new Date(d.getFullYear(),d.getMonth()+1,1)):compKey(d);
const CUR=compOf(T0),LAST=kAdd(CUR,-1);
function periodo(k){const[y,m]=k.split('-').map(Number);return {ini:new Date(y,m-2,21),fim:new Date(y,m-1,20)}}
const perLabel=k=>{const p=periodo(k);return fD(p.ini).slice(0,5)+' a '+fD(p.fim)};
function diasPer(k){const p=periodo(k);const r=[];for(let d=new Date(p.ini);d<=p.fim;d=addD(d,1))r.push(new Date(d));return r}
const hm=s=>{if(!s)return NaN;const[a,b]=String(s).split(':').map(Number);return a*60+b};
const fm=m=>{if(!m)return '';const s=m<0?'-':'';m=Math.abs(Math.round(m));return s+String(Math.floor(m/60)).padStart(2,'0')+':'+String(m%60).padStart(2,'0')};
const fmh=m=>N((m||0)/60,1)+'h';
const t5=s=>s?String(s).slice(0,5):'';
const uid=()=>Math.random().toString(36).slice(2,10);
const sleep=ms=>new Promise(r=>setTimeout(r,ms));

// ---------------------------------------------------------------- dados (Supabase)
function makeSupabaseApi(cfg){
 const sb=window.supabase.createClient(cfg.SUPABASE_URL,cfg.SUPABASE_ANON_KEY,{auth:{persistSession:true,autoRefreshToken:true,detectSessionInUrl:true}});
 const chk=r=>{if(r.error){const e=new Error(traduzErro(r.error));e.raw=r.error;throw e}return r.data};
 const filt=(x,f={})=>{for(const[k,v]of Object.entries(f.eq||{}))x=v===null?x.is(k,null):x.eq(k,v);for(const[k,v]of Object.entries(f.neq||{}))x=x.neq(k,v);
  for(const[k,v]of Object.entries(f.in||{}))x=x.in(k,v);for(const[k,v]of Object.entries(f.gte||{}))x=x.gte(k,v);for(const[k,v]of Object.entries(f.lte||{}))x=x.lte(k,v);
  for(const[k,v]of Object.entries(f.ilike||{}))x=x.ilike(k,v);if(f.notnull)f.notnull.forEach(k=>x=x.not(k,'is',null));return x};
 return {
  sb,
  async select(t,f={}){const out=[];const step=1000;let from=0;for(;;){let x=filt(sb.from(t).select(f.cols||'*'),f);if(f.order)x=x.order(f.order[0],{ascending:f.order[1]!==false});
    if(f.limit){x=x.limit(f.limit);return chk(await x)}x=x.range(from,from+step-1);const d=chk(await x);out.push(...d);if(d.length<step)return out;from+=step}},
  async insert(t,rows){return chk(await sb.from(t).insert(rows).select())},
  async update(t,match,patch){return chk(await filt(sb.from(t).update(patch),{eq:match}).select())},
  async upsert(t,rows,onConflict){return chk(await sb.from(t).upsert(rows,{onConflict}).select())},
  async remove(t,f){return chk(await filt(sb.from(t).delete(),f))},
  async rpc(n,a){return chk(await sb.rpc(n,a||{}))},
  async fn(n,body){const r=await sb.functions.invoke(n,{body});if(r.error){let msg=r.error.message,cod;try{const j=await r.error.context.json();msg=j.error||msg;cod=j.codigo}catch(e){}
    if(/Failed to send a request|not found|404/i.test(msg))msg='A função "'+n+'" ainda não foi publicada no Supabase (Edge Functions). Veja o passo a passo.';const e=new Error(msg);e.codigo=cod;throw e}return r.data},
  async signIn(email,password){return chk(await sb.auth.signInWithPassword({email,password}))},
  async signOut(){await sb.auth.signOut()},
  async session(){return (await sb.auth.getSession()).data.session},
  onAuth(cb){sb.auth.onAuthStateChange(cb)},
  async resetPassword(email){return chk(await sb.auth.resetPasswordForEmail(email,{redirectTo:location.origin+location.pathname}))},
  async updatePassword(password){return chk(await sb.auth.updateUser({password}))},
  async upload(path,file){return chk(await sb.storage.from('documentos').upload(path,file,{upsert:true,contentType:file.type||undefined}))},
  async signedUrl(path){return chk(await sb.storage.from('documentos').createSignedUrl(path,300)).signedUrl},
  async removeFile(path){return chk(await sb.storage.from('documentos').remove([path]))}};
}
function traduzErro(e){const m=(e&&(e.message||e.error_description))||String(e);
 if(/Invalid login credentials/i.test(m))return 'E-mail ou senha inválidos.';
 if(/Email not confirmed/i.test(m))return 'E-mail ainda não confirmado. Confirme pelo link recebido ou peça ao administrador.';
 if(/row-level security|permission denied|violates row-level/i.test(m))return 'Seu perfil não tem permissão para esta ação.';
 if(/duplicate key/i.test(m))return 'Já existe um registro com esses dados (valor repetido).';
 if(/ponto_obra_obrigatoria/.test(m))return 'Informe a obra do dia para quem trabalhou.';
 if(/ponto_marcacoes_ordem/.test(m))return 'Marcações fora de ordem (entrada, saída, entrada, saída).';
 if(/ponto_divisao/.test(m))return 'Na divisão do dia, a 2ª obra deve ser diferente da 1ª e ter horas.';
 if(/Failed to fetch|NetworkError/i.test(m))return 'Sem conexão com o servidor. Verifique a internet.';
 return m}

// ---------------------------------------------------------------- estado
const S={api:null,session:null,user:null,perfil:null,perms:{},obrasLib:null,route:'inicio',params:{},f:{},ref:{},open:{},dados:{},pd:null,draft:{}};
const perm=(m,a)=>!!(S.perfil&&(S.perfil.master||(S.perms[m]&&S.perms[m][a])));
const ROUTE_MOD={inicio:null,colab:'colab',ficha:'colab',admissao:'admissao',admdet:'admissao',ponto:'ponto',rateio:'rateio',usuarios:'usuarios',perfis:'usuarios',cadastros:'cadastros',auditoria:'auditoria'};
const can=r=>{const m=ROUTE_MOD[r];if(m===undefined)return S.perfil&&S.perfil.master;return m===null||perm(m,'ver')};
const dis=(a,m)=>perm(m,a)?'':'disabled title="Seu perfil não tem permissão para esta ação"';
const obraLib=id=>!id||S.perfil.master||S.user.todas_obras||(S.obrasLib||[]).includes(id);
const obrasUser=()=>S.ref.obras.filter(o=>o.ativa&&obraLib(o.id));
const obraNome=id=>(S.ref.obras.find(o=>o.id===id)||{}).nome||'';
const funcaoNome=id=>(S.ref.funcoes.find(o=>o.id===id)||{}).nome||'';
const userNome=id=>{const u=(S.ref.usuarios||[]).find(x=>x.id===id);return u?u.nome:(id?'usuário':'sistema')};
const isFer=d=>!!S.ref.feriadosSet&&S.ref.feriadosSet.has(dk(d));
function carga(d){const j=S.ref.jornada||{};if(isFer(d)||d.getDay()===0||d.getDay()===6)return 0;return d.getDay()===5?(j.sexta_min??480):(j.seg_qui_min??540)}
const TOL=()=>(S.ref.jornada||{}).tolerancia_min??10;

// ---------------------------------------------------------------- interface comum
function pill(t,c){return `<span class="pill ${c}">${esc(t)}</span>`}
function kc(l,v,h,st,act){return `<div class="card kpi ${st||''}" ${act?`data-act="go" data-r="${act}" style="cursor:pointer"`:''}><div class="l">${l}</div><div class="v">${v}</div><div class="h">${h||''}</div></div>`}
function toast(m,erro){document.querySelectorAll('.toast').forEach(x=>x.remove());const t=document.createElement('div');t.className='toast';if(erro)t.style.background='var(--bad)';t.textContent=m;document.body.appendChild(t);setTimeout(()=>t.remove(),erro?6000:3000)}
function openModal(h,wide){closeModal();const d=document.createElement('div');d.className='modal-bg';d.id='modal';d.innerHTML=`<div class="modal" role="dialog" ${wide?'style="max-width:1000px"':''}>${h}</div>`;d.addEventListener('click',e=>{if(e.target===d)closeModal()});document.body.appendChild(d)}
function closeModal(){const m=$('#modal');if(m)m.remove()}
const optList=(L,sel,vazio)=>(vazio!==undefined?`<option value="">${esc(vazio)}</option>`:'')+L.map(o=>`<option value="${esc(o.id)}" ${o.id===sel?'selected':''}>${esc(o.nome)}</option>`).join('');
function csv(nome,rows){const t=rows.map(r=>r.map(v=>'"'+String(v??'').replace(/"/g,'""')+'"').join(';')).join('\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob(['﻿'+t],{type:'text/csv'}));a.download=nome;document.body.appendChild(a);a.click();a.remove();evento('Exportou CSV',nome)}
async function evento(acao,det){try{await S.api.rpc('registrar_evento',{p_acao:acao,p_detalhe:det||null})}catch(e){}}
const DOC_CSS='body{font-family:Arial,Helvetica,sans-serif;font-size:11pt;line-height:1.5;color:#000}h1{font-size:13pt;text-align:center;margin:0 0 14pt}h2{font-size:11pt;margin:12pt 0 4pt}p{margin:0 0 6pt}.sig{width:100%;margin:34pt 0 6pt;border-collapse:collapse}.sig td{width:50%;padding:0 18pt;text-align:center;vertical-align:top;font-size:10pt}.sl{border-top:1px solid #000;margin-bottom:4pt}';
function docPrint(html){let p=$('#printArea');if(!p){p=document.createElement('div');p.id='printArea';document.body.appendChild(p)}
 p.innerHTML=`<style>${DOC_CSS.replace(/(^|\})([^{}@]+)\{/g,(m,a,b)=>a+b.split(',').map(s=>'#printArea '+s.trim().replace(/^body$/,'')).join(',')+'{')}</style>`+html;
 document.body.classList.add('pdoc');setTimeout(()=>{window.print();setTimeout(()=>document.body.classList.remove('pdoc'),400)},150)}
function docWord(nome,html){const full=`<html><head><meta charset="utf-8"><title>${esc(nome)}</title><style>@page{margin:2cm}${DOC_CSS}</style></head><body>${html}</body></html>`;const a=document.createElement('a');a.href=URL.createObjectURL(new Blob(['﻿'+full],{type:'application/msword'}));a.download=nome.replace(/[^\wÀ-ú\- ]/g,'').replace(/\s+/g,'_')+'.doc';document.body.appendChild(a);a.click();a.remove()}
const LOGO=()=>`<img src="logo.png" alt="Avante Engenharia" class="logo-img logo-sm">`;
// ---------------------------------------------------------------- menu
const ICON={home:'<path d="M3 10l9-7 9 7v10a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2z"/><path d="M9 22V12h6v10"/>',rh:'<path d="M16 20v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2"/><circle cx="9" cy="7" r="4"/><path d="M22 20v-2a4 4 0 0 0-3-3.87M16 3.13a4 4 0 0 1 0 7.75"/>',
 sst:'<path d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z"/><path d="M9 12l2 2 4-4"/>',log:'<path d="M1 3h15v13H1zM16 8h4l3 3v5h-7z"/><circle cx="5.5" cy="18.5" r="2.5"/><circle cx="18.5" cy="18.5" r="2.5"/>',
 eng:'<path d="M2 20h20M4 20V9l8-5 8 5v11M9 20v-6h6v6"/>',fin:'<path d="M12 1v22M17 5H9.5a3.5 3.5 0 0 0 0 7h5a3.5 3.5 0 0 1 0 7H6"/>',sup:'<path d="M21 16V8a2 2 0 0 0-1-1.73l-7-4a2 2 0 0 0-2 0l-7 4A2 2 0 0 0 3 8v8a2 2 0 0 0 1 1.73l7 4a2 2 0 0 0 2 0l7-4A2 2 0 0 0 21 16z"/>',
 adm:'<circle cx="12" cy="12" r="3"/><path d="M12 1v3M12 20v3M4.2 4.2l2.1 2.1M17.7 17.7l2.1 2.1M1 12h3M20 12h3M4.2 19.8l2.1-2.1M17.7 6.3l2.1-2.1"/>',eye:'<path d="M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z"/><circle cx="12" cy="12" r="3"/>'};
const ico=(k,s)=>`<svg width="${s||18}" height="${s||18}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${ICON[k]}</svg>`;
const SECTORS=[
 {id:'rh',t:'Recursos Humanos',icon:'rh',items:[{grp:'func',t:'Funcionários',sub:[{id:'colab',t:'Cadastro de funcionários'},{id:'admissao',t:'Nova admissão'}]},{id:'ponto',t:'Folha de ponto'},{id:'rateio',t:'Rateio da folha'}]},
 {id:'sst',t:'Saúde e Segurança (SESMT)',icon:'sst',items:[{id:'soon_sst',t:'Próxima fase',soon:1}]},
 {id:'log',t:'Logística',icon:'log',items:[{id:'soon_log',t:'Próxima fase',soon:1}]},
 {id:'eng',t:'Engenharia e Operação',icon:'eng',items:[{id:'soon_eng',t:'Próxima fase',soon:1}]},
 {id:'fin',t:'Financeiro',icon:'fin',items:[{id:'soon_fin',t:'Próxima fase',soon:1}]},
 {id:'sup',t:'Suprimentos',icon:'sup',items:[{id:'soon_sup',t:'Próxima fase',soon:1}]},
 {id:'adm',t:'Administração',icon:'adm',items:[{id:'usuarios',t:'Usuários'},{id:'perfis',t:'Perfis e permissões'},{id:'cadastros',t:'Cadastros e configurações'},{id:'auditoria',t:'Auditoria'}]}];
['soon_sst','soon_log','soon_eng','soon_fin','soon_sup'].forEach(r=>ROUTE_MOD[r]=null);
const flat=s=>s.items.flatMap(i=>i.sub?i.sub:[i]);
const TITLES={inicio:'Início',ficha:'Ficha do funcionário',admdet:'Processo de admissão'};SECTORS.forEach(s=>flat(s).forEach(i=>TITLES[i.id]=i.t));
const PARENT={ficha:'colab',admdet:'admissao'};
function crumbs(r){const rr=PARENT[r]||r;for(const s of SECTORS)for(const i of s.items){if(i.id===rr)return [s.t,i.t].concat(PARENT[r]?[TITLES[r]]:[]);if(i.sub){const x=i.sub.find(y=>y.id===rr);if(x)return [s.t,i.t,x.t].concat(PARENT[r]?[TITLES[r]]:[])}}return [TITLES[r]||'']}
function navHTML(){const cur=PARENT[S.route]||S.route;
 return `<a class="sec-h home ${cur==='inicio'?'cur':''}" data-act="go" data-r="inicio">${ico('home')}<span>Início</span></a>`+SECTORS.map(s=>{const its=s.items.filter(i=>i.sub?i.sub.some(x=>can(x.id)):can(i.id));if(!its.length)return '';const has=flat(s).some(i=>i.id===cur);const open=S.open[s.id]??has;
  return `<div class="sec ${open?'open':''}"><button class="sec-h ${has?'cur':''}" data-act="sec" data-s="${s.id}">${ico(s.icon)}<span>${s.t}</span><svg class="chev" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M9 6l6 6-6 6"/></svg></button>
  ${open?`<nav class="nav sec-b">${its.map(i=>i.sub?`<a class="grp open"><span>${i.t}</span></a>${i.sub.filter(x=>can(x.id)).map(x=>`<a data-act="go" data-r="${x.id}" class="nsub ${cur===x.id?'active':''}">${x.t}</a>`).join('')}`:`<a data-act="go" data-r="${i.id}" class="${cur===i.id?'active':''}">${i.t}${i.soon?'<span class="tag">em breve</span>':''}</a>`).join('')}</nav>`:''}</div>`}).join('')}
function shell(inner){return `<div class="app"><aside class="side" id="side"><div style="padding:4px 6px 14px">${LOGO()}</div>${navHTML()}</aside>
 <div class="main"><header class="top"><div style="display:flex;gap:10px;align-items:center;min-width:0"><button class="btn sm menu-btn" data-act="menu">Menu</button><span class="small muted crumbs">${crumbs(S.route).map(esc).join(' <span>›</span> ')}</span></div>
 <div style="display:flex;gap:10px;align-items:center"><button class="btn sm bell" data-act="notif" aria-label="Notificações"><svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M18 8A6 6 0 0 0 6 8c0 7-3 9-3 9h18s-3-2-3-9M13.73 21a2 2 0 0 1-3.46 0"/></svg>${S.naoLidas?`<span class="nbadge">${S.naoLidas}</span>`:''}</button>
 <div style="text-align:right"><div style="font-weight:600">${esc(S.user.nome)}</div><div class="small muted">${esc(S.perfil.nome)}</div></div><button class="btn sm" data-act="senha">Senha</button><button class="btn sm" data-act="logout">Sair</button></div></header>
 <section class="content" id="content">${inner}</section></div></div>`}

// ---------------------------------------------------------------- roteamento
const PAGES={};
let _rendering=false;
function render(){if(_rendering)return;_rendering=true;try{
  if(!S.user){$('#app').innerHTML=loginHTML();updLoginBtn();return}
  if(!can(S.route))S.route='inicio';const p=PAGES[S.route];
  $('#app').innerHTML=shell(S.dados[S.route]===undefined&&p.load?'<div class="loading"><span class="spin"></span>Carregando…</div>':safeHtml(p));
 }finally{_rendering=false}}
function safeHtml(p){try{return p.html()}catch(e){console.error(e);return `<div class="note" style="background:var(--bad-soft)">Erro ao montar a tela: ${esc(e.message)}</div>`}}
async function go(r,params){S.route=r;S.params=params||{};S.pd=null;$('#side')?.classList.remove('open');await reload();window.scrollTo(0,0)}
async function reload(){const r=S.route;const p=PAGES[r];if(p&&p.load){delete S.dados[r];render();try{S.dados[r]=await p.load()||{}}catch(e){S.dados[r]={erro:e.message}}}if(S.route!==r)return;
 if(S.dados[r]&&S.dados[r].erro){$('#content').innerHTML=`<div class="note" style="background:var(--bad-soft)"><b>Não foi possível carregar.</b> ${esc(S.dados[r].erro)}</div><button class="btn" data-act="go" data-r="${r}">Tentar de novo</button>`;return}
 render()}
function D(){return S.dados[S.route]||{}}

