 pRepetir:async()=>{const ids=Object.keys(S.pd.rows).map(k=>k.split('|')[0]);const d=pdk(S.params.data);const prev=await S.api.select('ponto',{cols:'funcionario_id,data,obra_id,ocorrencia',gte:{data:dk(addD(d,-10))},lte:{data:dk(addD(d,-1))},order:['data',false]});let n=0;
  Object.entries(S.pd.rows).forEach(([k,r])=>{if(r.obra_id||r.ocorrencia!=='TRABALHADO')return;const p=prev.find(x=>x.funcionario_id===k.split('|')[0]&&x.ocorrencia==='TRABALHADO'&&x.obra_id);if(p){r.obra_id=p.obra_id;n++}});S.pd.dirty=true;toast(n+' funcionário(s) com a obra do último dia trabalhado. Confira antes de salvar.');render()},
