 pReabrir:async()=>{await S.api.upsert('ponto_dia_status',[{data:S.params.data,status:'Rascunho',usuario_id:S.user.id,em:new Date().toISOString()}],'data');await evento('Reabriu ponto do dia',S.params.data);S.pd=null;reload()},
