function pontoEspelho(){const {L,fs,st}=D();const f=fs.find(x=>x.id===S.params.emat);if(!f)return '<p class="muted">Nenhum funcionário.</p>';const ed=perm('ponto','editar');const pd=draftEsp();let T={normal:0,he50:0,he100:0,atraso:0,falta:0,trab:0};const H={};
 const rows=diasPer(S.params.comp).map(d=>{const k=f.id+'|'+dk(d);const fut=d>=T0||!ativoNoDia(f,d);const r=fut?null:pd.rows[k];const o=calcDia(r,d);Object.keys(T).forEach(x=>T[x]+=o[x]);horasObra(r,o).forEach(h=>H[h.obra]=(H[h.obra]||0)+h.min);
  const first=`<td style="white-space:nowrap">${DOW[d.getDay()].slice(0,3)} ${fD(d).slice(0,5)}${isFer(d)?' <span class="tag">feriado</span>':''}</td>`;const s=st.find(x=>String(x.data).slice(0,10)===dk(d));
  if(!fut&&ed)return rowHTML(k,first,s&&s.status==='Aprovado'&&!perm('ponto','aprovar'));
  return `<tr>${first}<td colspan="5">${fut?'':r&&!vazioR(r)?(r.ocorrencia==='TRABALHADO'?`${r.entrada1} – ${r.saida1} · ${r.entrada2} – ${r.saida2}`:ocNome(r.ocorrencia)):(o.carga?pill('sem lançamento','warn'):'')}</td><td class="num">${fut?'':calcCell(vazioR(r)?null:o)}</td><td colspan="3" class="small">${r&&r.obra_id?esc(obraNome(r.obra_id))+(r.obra2_id?' / '+esc(obraNome(r.obra2_id)):''):''}</td></tr>`}).join('');
 return `<div class="toolbar"><select data-esel="emat" style="min-width:260px">${L.map(x=>`<option value="${x.id}" ${x.id===f.id?'selected':''}>${esc(x.nome)} · ${esc(x.matricula)}</option>`).join('')}</select><select data-esel="comp">${[kAdd(CUR,-3),kAdd(CUR,-2),LAST,CUR].map(k=>`<option value="${k}" ${k===S.params.comp?'selected':''}>${compLabel(k)} · ${perLabel(k)}</option>`).join('')}</select><span class="sp"></span>${ed?`<button class="btn sm" data-act="pPadrao">Preencher horário padrão nos dias úteis vazios</button>`:''}<button class="btn sm" data-act="ePrint">Imprimir espelho</button><button class="btn sm" data-act="ePrintTodos">Imprimir todos do período</button></div>
 <div class="card"><dl class="ficha" style="grid-template-columns:110px 1fr 110px 1fr;margin:0 0 14px"><dt>Nome</dt><dd><b>${esc(f.nome)}</b></dd><dt>Admissão</dt><dd>${fD(f.data_admissao)}</dd><dt>Cargo</dt><dd>${esc(funcaoNome(f.funcao_id))}</dd><dt>Matrícula</dt><dd>${esc(f.matricula)}</dd><dt>CPF</dt><dd>${esc(f.cpf||'')}</dd><dt>Período</dt><dd>${perLabel(S.params.comp)}</dd></dl>
 <div class="tablewrap"><table>${PHEAD('Dia')}<tbody>${rows}</tbody></table></div>
 <div class="grid mt" style="grid-template-columns:repeat(auto-fit,minmax(140px,1fr))">${[['Hora normal',T.normal],['Hora extra 50%',T.he50],['Hora extra 100%',T.he100],['Atraso',T.atraso],['Falta',T.falta]].map(x=>`<div class="card kpi"><div class="l">${x[0]}</div><div class="v" style="font-size:20px">${fm(x[1])||'00:00'}</div></div>`).join('')}</div>
 <p class="small mt"><b>Horas por obra:</b> ${Object.entries(H).sort((a,b)=>b[1]-a[1]).map(([o,m])=>pill(obraNome(o)+' · '+fmh(m),'info')).join(' ')||'—'}</p></div>
 ${ed?`<div class="toolbar mt"><span class="sp"></span><span class="small muted" id="pdirty"></span><button class="btn" data-act="pDescartar">Descartar</button><button class="btn primary" data-act="pSalvar">Salvar alterações do espelho</button></div>`:''}`}
const hx=m=>{m=Math.round(m||0);return Math.floor(m/60)+':'+String(m%60).padStart(2,'0')};const hxs=m=>hx(m)+':00';const hh=s=>{const m=hm(s);return isNaN(m)?'':hx(m)};
function espelhoExcel(f,k,pts){const p=periodo(k);let T={carga:0,atraso:0,falta:0,he50:0,he100:0};const get=d=>pts.find(x=>x.funcionario_id===f.id&&String(x.data).slice(0,10)===dk(d));
 const rows=diasPer(k).map(d=>{const r0=get(d);const r=r0?limpa(r0):null;const o=calcDia(r,d);const cinza=d.getDay()===0||d.getDay()===6||isFer(d);const fut=d>=T0||!ativoNoDia(f,d);
  if(!fut)T.carga+=o.carga;T.atraso+=o.atraso;T.falta+=o.falta;T.he50+=o.he50;T.he100+=o.he100;
  let m;if(r&&r.ocorrencia!=='TRABALHADO')m=`<td colspan="4" class="c">${esc(ocNome(r.ocorrencia).toUpperCase())}</td>`;else if(!r&&isFer(d)&&!fut)m='<td colspan="4" class="c">FERIADO</td>';else m=['entrada1','saida1','entrada2','saida2'].map(x=>`<td class="c">${r&&r[x]?hh(r[x]):''}</td>`).join('');
  return `<tr class="${cinza?'g':''}"><td class="l">${DOW[d.getDay()]}</td><td class="c">${d.getDate()}</td>${m}<td class="c">${fut?'':hx(o.trab)}</td><td class="c">${fut?'':hx(o.carga)}</td><td class="c">${o.atraso?hx(o.atraso):''}</td><td class="c">${o.falta?hx(o.falta):''}</td><td class="c">${o.he50?hx(o.he50):''}</td><td class="c">${o.he100?hx(o.he100):''}</td></tr>`}).join('');
 return `<div class="esx"><table class="tt"><tr><td class="lg"><img src="logo.png" alt=""></td><td class="ti">ESPELHO DE PONTO</td></tr></table>
 <table class="hd"><tr><td class="k">NOME:</td><td>${esc(f.nome.toUpperCase())}</td><td class="k r">ADMISSÃO:</td><td>${fD(f.data_admissao)}</td></tr><tr><td class="k">CARGO:</td><td>${esc(funcaoNome(f.funcao_id).toUpperCase())}</td><td class="k r">MATRÍCULA:</td><td>${esc(f.matricula)}</td></tr><tr><td class="k">CPF:</td><td>${esc(f.cpf||'')}</td><td class="k r">PERÍODO:</td><td>${fD(p.ini)} a ${fD(p.fim)}</td></tr></table>
 <table class="gr"><colgroup><col style="width:10%"><col style="width:5%"><col style="width:8%"><col style="width:8%"><col style="width:8%"><col style="width:8%"><col style="width:11%"><col style="width:8%"><col style="width:8%"><col style="width:8%"><col style="width:9%"><col style="width:9%"></colgroup>
 <tr class="h"><td colspan="2">Data</td><td colspan="4">Marcações</td><td>Trabalhada</td><td>Normal</td><td>Atraso</td><td>Falta</td><td>50%</td><td>100 %</td></tr>${rows}</table>
 <table class="tot"><tr><td class="a">HORA NORMAL</td><td class="b">${hxs(Math.max(0,T.carga-T.atraso-T.falta))}</td><td class="sp"></td><td class="a c">ATRASO</td><td class="b">${hxs(T.atraso)}</td></tr><tr><td class="a">HORA EXTRA 50%</td><td class="b">${hxs(T.he50)}</td><td class="sp"></td><td class="a c">FALTA</td><td class="b">${hxs(T.falta)}</td></tr><tr><td class="a">HORA EXTRA 100%</td><td class="b">${hxs(T.he100)}</td><td class="sp"></td><td></td><td></td></tr></table>
 <table class="as"><tr><td><div></div>Assinatura do Funcionário</td><td class="sp"></td><td><div></div>Assinatura da Chefia</td></tr></table></div>`}
