function pontoSit(){const {fs,pt,st}=D();const dias=diasPer(CUR).filter(d=>d<=T0);
 return `<p class="small muted">Competência ${compLabel(CUR)} (${perLabel(CUR)}). Clique no dia para abrir o lançamento.</p><div class="card tablewrap"><table><thead><tr><th></th>${dias.map(d=>`<th style="text-align:center;padding:6px 4px">${String(d.getDate()).padStart(2,'0')}<br><span class="small">${DOW[d.getDay()].slice(0,3)}</span></th>`).join('')}</tr></thead><tbody>
 <tr><td><b>Situação</b></td>${dias.map(d=>{const s=st.find(x=>String(x.data).slice(0,10)===dk(d));let cls='neutral',t='';if(s){cls=s.status==='Aprovado'?'ok':s.status==='Enviado'?'info':'warn';t=s.status[0]}else if(carga(d)){cls=dk(d)===dk(T0)?'warn':'bad';t='!'}return `<td style="text-align:center;padding:4px 2px">${t?`<span class="pill ${cls}" style="cursor:pointer;padding:2px 6px" data-act="pIr" data-d="${dk(d)}" title="${s?s.status:'Não lançado'}">${t}</span>`:''}</td>`}).join('')}</tr>
 <tr><td style="white-space:nowrap"><b>Lançados</b></td>${dias.map(d=>{const a=fs.filter(f=>ativoNoDia(f,d)).length;const n=pt.filter(x=>String(x.data).slice(0,10)===dk(d)).length;return `<td style="text-align:center;font-size:11px;${carga(d)&&n<a?'color:var(--bad);font-weight:700':'color:var(--muted)'}">${carga(d)||n?n+'/'+a:''}</td>`}).join('')}</tr>
 <tr><td style="white-space:nowrap"><b>Em 2 obras</b></td>${dias.map(d=>{const n=pt.filter(x=>String(x.data).slice(0,10)===dk(d)&&x.obra2_id).length;return `<td style="text-align:center;font-size:11px" class="muted">${n||''}</td>`}).join('')}</tr></tbody></table>
 <p class="small muted mt">${pill('A','ok')} aprovado · ${pill('E','info')} enviado · ${pill('R','warn')} rascunho · ${pill('!','bad')} dia útil sem lançamento</p></div>`}
// ================================================================ RATEIO DA FOLHA
const ENC=[['ferias','Provisão de férias + 1/3','pct_ferias','valor_ferias'],['decimo','Provisão de 13º salário','pct_decimo','valor_decimo'],['inss','INSS (parte da empresa)','pct_inss','valor_inss'],['fgts','FGTS','pct_fgts','valor_fgts']];
PAGES.rateio={async load(){const k=S.params.comp||LAST;S.params.comp=k;const p=periodo(k);const[y,m]=k.split('-').map(Number);const mi=new Date(y,m-1,1),mf=new Date(y,m,0);
 const ini=p.ini<mi?p.ini:mi,fim=p.fim>mf?p.fim:mf;
 const[fs,rem,pt,cp,snap]=await Promise.all([S.api.select('funcionarios',{cols:'id,matricula,nome,funcao_id,data_admissao,data_desligamento,status,obra_referencia_id',order:['nome']}),S.api.select('funcionarios_remuneracao').catch(()=>null),S.api.select('ponto',{gte:{data:dk(ini)},lte:{data:dk(fim)}}),S.api.select('competencias',{eq:{id:k}}),S.api.select('rateio_fechamento',{eq:{competencia_id:k}})]);
 return {k,fs,rem,pt,cp:cp[0]||null,snap}},
 html(){const d=D();const k=d.k;if(!d.rem)return `<h1>Rateio da folha</h1><div class="note">Seu perfil não tem acesso aos salários, necessários para calcular o custo por obra.</div>`;
 const fech=d.cp&&d.cp.status==='Fechada';const R=fech&&d.snap.length?rateioSnap(d):calcRateio(d);const ed=(perm('rateio','editar')||perm('rateio','aprovar'))&&!fech;const aberta=k===CUR||periodo(k).fim>=T0;const cp=d.cp||{};
 const ob=R.porObra.filter(o=>o.total>0).sort((a,b)=>b.total-a.total);const F=['sal','he','ferias','decimo','inss','fgts','va','total'];
 return `<h1>Rateio da folha por obra</h1><p class="sub">Ao fim de cada período (21 a 20), o custo de mão de obra é distribuído entre as obras na proporção das horas lançadas no ponto, como na aba RATEIO GERAL da planilha.</p>
 <div class="toolbar"><select data-rcomp="1">${[kAdd(CUR,-5),kAdd(CUR,-4),kAdd(CUR,-3),kAdd(CUR,-2),LAST,CUR].map(x=>`<option value="${x}" ${x===k?'selected':''}>${compLabel(x)} · ${perLabel(x)}${x===CUR?' · em apuração':''}</option>`).join('')}</select><span class="sp"></span>
 ${fech?pill('Fechada em '+fD(cp.fechada_em),'neutral')+(S.perfil.master?' <button class="btn sm" data-act="rReabrir">Reabrir</button>':''):aberta?pill('Período em apuração: parcial até ontem','info'):`<button class="btn sm primary" data-act="rFechar" ${dis('aprovar','rateio')}>Fechar competência</button>`} <button class="btn sm" data-act="rCsv" ${dis('exportar','rateio')}>Exportar no formato da planilha</button></div>
 <div class="card"><h3>INSS, FGTS, férias e 13º de ${compLabel(k)}</h3><p class="small muted" style="margin-top:-6px">Informe os valores da folha enviados pela contabilidade. Cada um é rateado entre as obras proporcionalmente ao salário + horas extras de cada uma. Sem valor informado, o portal estima pelo percentual.</p>
 <div class="tablewrap"><table><thead><tr><th>Item</th><th class="num">Valor da folha (R$)</th><th class="num">Percentual estimado</th><th>Em uso</th><th class="num">Total rateado</th></tr></thead><tbody>${ENC.map(([x,l,pc,vc])=>`<tr><td><b>${l}</b></td><td class="num"><input type="number" step="0.01" data-enc="${vc}" value="${cp[vc]??''}" placeholder="não informado" style="width:150px;text-align:right" ${ed?'':'disabled'}></td><td class="num"><input type="number" step="0.01" data-enc="${pc}" value="${cp[pc]??{pct_ferias:14.32,pct_decimo:10.7,pct_inss:26.8,pct_fgts:8}[pc]}" style="width:80px;text-align:right" ${ed?'':'disabled'}> %</td><td>${R.fonte[x]==='real'?pill('Valor real','ok'):pill('Estimado','warn')}</td><td class="num"><b>${BRL2(ob.reduce((s,o)=>s+o[x],0))}</b></td></tr>`).join('')}</tbody></table></div></div>
 ${R.semLanc&&!fech?`<div class="note mt"><b>${R.semLanc}</b> dia(s) útil(eis) sem lançamento de ponto no período. Dias sem lançamento não entram nas horas; revise antes de fechar.</div>`:''}
 <div class="card mt tablewrap"><h3>Resumo por obra · ${compLabel(k)}</h3><table><thead><tr><th>Obra</th><th class="num">Pessoas</th><th class="num">Horas</th><th class="num">Salários</th><th class="num">H. extras</th><th class="num">Férias</th><th class="num">13º</th><th class="num">INSS</th><th class="num">FGTS</th><th class="num">VA</th><th class="num">Total</th><th class="num">%</th></tr></thead><tbody>
 ${ob.map(o=>`<tr><td>${esc(obraNome(o.obra)||'Sem obra')}</td><td class="num">${o.pessoas.size}</td><td class="num">${N(o.horas/60)}</td>${F.map(f=>`<td class="num">${f==='total'?'<b>'+BRL(o[f])+'</b>':BRL(o[f])}</td>`).join('')}<td class="num">${P(R.total?o.total/R.total*100:0)}</td></tr>`).join('')||'<tr><td colspan="12" class="muted">Sem dados no período.</td></tr>'}</tbody>
 <tfoot><tr><td>Total</td><td></td><td class="num">${N(ob.reduce((s,o)=>s+o.horas,0)/60)}</td>${F.map(f=>`<td class="num">${BRL(ob.reduce((s,o)=>s+o[f],0))}</td>`).join('')}<td class="num">100%</td></tr></tfoot></table></div>
 <div class="card mt tablewrap"><h3>Horas por funcionário e obra</h3><table><thead><tr><th>Funcionário</th><th class="num">Custo total</th><th class="num">Horas</th>${ob.map(o=>`<th class="num" style="white-space:normal;min-width:80px">${esc(obraNome(o.obra))}</th>`).join('')}</tr></thead><tbody>${R.pessoas.map(x=>`<tr><td><a class="lp-link" data-act="abrirEspelho" data-id="${x.f.id}">${esc(x.f.nome)}</a></td><td class="num">${BRL(x.total)}</td><td class="num">${N(x.ht/60,1)}</td>${ob.map(o=>`<td class="num">${x.horas[o.obra]?N(x.horas[o.obra]/60,1):''}</td>`).join('')}</tr>`).join('')}</tbody></table><p class="small muted">Quem não trabalhou nenhuma hora (férias, afastamento) tem o custo lançado na obra de referência do cadastro.</p></div>`}};
function resumoFunc(f,k,pt){const p=periodo(k);const t={he50:0,he100:0,falta:0,atraso:0,semLanc:0,horas:{}};const mine=pt.filter(x=>x.funcionario_id===f.id);
 diasPer(k).forEach(d=>{if(d>=T0||!ativoNoDia(f,d))return;const r0=mine.find(x=>String(x.data).slice(0,10)===dk(d));const r=r0?limpa(r0):null;const o=calcDia(r,d);t.he50+=o.he50;t.he100+=o.he100;t.falta+=o.falta;t.atraso+=o.atraso;if(!r&&o.carga)t.semLanc++;horasObra(r,o).forEach(h=>t.horas[h.obra]=(t.horas[h.obra]||0)+h.min)});return t}
function vaMes(f,rm,k,pt){const[y,m]=k.split('-').map(Number);const ini=new Date(y,m-1,1),fim=new Date(y,m,0);const adm=pdk(f.data_admissao);if(adm>fim)return 0;const de=adm>ini?adm:ini;const dias=Math.min(30,dd(de,fim)+1);
 const faltas=pt.filter(x=>x.funcionario_id===f.id&&x.ocorrencia==='FALTA'&&pdk(x.data)>=ini&&pdk(x.data)<=fim).length;const prop=(+rm.va_valor||0)*dias/30;return prop-(faltas===0?0:faltas===1?prop*.25:faltas===2?prop*.5:prop)}
function calcRateio(d){const {k,fs,rem,pt,cp}=d;const p=periodo(k);const c=cp||{};const pessoas=[];let tb=0,semLanc=0;const esc0=(S.ref.obras.find(o=>o.nome==='ESCRITÓRIO')||S.ref.obras[0]||{}).id;
 fs.forEach(f=>{const adm=pdk(f.data_admissao);if(adm>p.fim||(f.data_desligamento&&pdk(f.data_desligamento)<p.ini))return;const rm=rem.find(x=>x.funcionario_id===f.id);if(!rm)return;
  const R=resumoFunc(f,k,pt);semLanc+=R.semLanc;const de=adm>p.ini?adm:p.ini;const fimf=f.data_desligamento&&pdk(f.data_desligamento)<p.fim?pdk(f.data_desligamento):p.fim;const ate=fimf<T0?fimf:addD(T0,-1);const tot=dd(p.ini,p.fim)+1;const fr=Math.max(0,Math.min(1,(dd(de,ate)+1)/tot));
  const sb=+rm.salario*(1+(+rm.adicional_pct||0)/100);const vh=sb/220;const base=sb*fr;const he=R.he50/60*vh*1.5+R.he100/60*vh*2;const desc=(R.falta+R.atraso)/60*vh;const bruto=Math.max(0,base+he-desc);const va=vaMes(f,rm,k,pt)*fr;
  tb+=bruto;pessoas.push({f,R,base,he,desc,bruto,va,horas:R.horas,ht:Object.values(R.horas).reduce((s,v)=>s+v,0)})});
 const coef={},fonte={};ENC.forEach(([x,,pc,vc])=>{const v=c[vc];if(v!==null&&v!==undefined&&v!==''&&tb){coef[x]=+v/tb;fonte[x]='real'}else{coef[x]=(c[pc]??{pct_ferias:14.32,pct_decimo:10.7,pct_inss:26.8,pct_fgts:8}[pc])/100;fonte[x]='estimado'}});
 const res={};const add=o=>res[o]=res[o]||{obra:o,pessoas:new Set(),horas:0,sal:0,he:0,ferias:0,decimo:0,inss:0,fgts:0,va:0,total:0};const linhas=[];
 pessoas.forEach(x=>{ENC.forEach(([e])=>x[e]=x.bruto*coef[e]);x.total=x.bruto+x.ferias+x.decimo+x.inss+x.fgts+x.va;let hs=Object.entries(x.horas);const sem=!x.ht;if(sem)hs=[[x.f.obra_referencia_id||esc0,1]];const tt=x.ht||1;
  hs.forEach(([o,min])=>{const f=min/tt;const r=add(o);r.pessoas.add(x.f.id);r.horas+=sem?0:min;r.sal+=(x.base-x.desc)*f;r.he+=x.he*f;['ferias','decimo','inss','fgts','va','total'].forEach(e=>r[e]+=x[e]*f);linhas.push({f:x.f,obra:o,min:sem?0:min,x,fr:f})})});
 const porObra=Object.values(res);return {porObra,pessoas,linhas,total:porObra.reduce((s,o)=>s+o.total,0),semLanc,fonte,coef,tb}}
function rateioSnap(d){const res={};const pes={};d.snap.forEach(s=>{const r=res[s.obra_id]=res[s.obra_id]||{obra:s.obra_id,pessoas:new Set(),horas:0,sal:0,he:0,ferias:0,decimo:0,inss:0,fgts:0,va:0,total:0};r.pessoas.add(s.funcionario_id);r.horas+=s.minutos;r.sal+=+s.salario;r.he+=+s.horas_extras;['ferias','decimo','inss','fgts','va','total'].forEach(e=>r[e]+=+s[e]);
  const f=d.fs.find(x=>x.id===s.funcionario_id)||{id:s.funcionario_id,nome:'?'};const p=pes[f.id]=pes[f.id]||{f,total:0,ht:0,horas:{}};p.total+=+s.total;p.ht+=s.minutos;p.horas[s.obra_id]=(p.horas[s.obra_id]||0)+s.minutos});
 const porObra=Object.values(res);const cp=d.cp;const fonte={};ENC.forEach(([x,,,vc])=>fonte[x]=cp[vc]!=null?'real':'estimado');return {porObra,pessoas:Object.values(pes).sort((a,b)=>a.f.nome.localeCompare(b.f.nome)),total:porObra.reduce((s,o)=>s+o.total,0),semLanc:0,fonte}}
FIELD.push(async ev=>{const t=ev.target;if(t.dataset.rcomp){if(ev.type==='change'){S.params.comp=t.value;reload()}return true}
 if(t.dataset.enc){if(ev.type!=='change')return true;const d=D();const p=periodo(d.k);const v=t.value===''?null:+t.value;const row=Object.assign({id:d.k,inicio:dk(p.ini),fim:dk(p.fim)},d.cp?{}:{},{[t.dataset.enc]:v});
  const r=(await S.api.upsert('competencias',[row],'id'))[0];d.cp=r;toast('Valor salvo');render();return true}return false});
Object.assign(ACT,{
 rFechar:async()=>{const d=D();const R=calcRateio(d);if(R.semLanc&&!confirm(R.semLanc+' dia(s) útil(eis) sem lançamento de ponto. Fechar mesmo assim? Depois de fechada, o ponto do período fica bloqueado.'))return;
  const rows=R.linhas.map(l=>({competencia_id:d.k,funcionario_id:l.f.id,obra_id:l.obra,minutos:Math.round(l.min),salario:+((l.x.base-l.x.desc)*l.fr).toFixed(2),horas_extras:+(l.x.he*l.fr).toFixed(2),ferias:+(l.x.ferias*l.fr).toFixed(2),decimo:+(l.x.decimo*l.fr).toFixed(2),inss:+(l.x.inss*l.fr).toFixed(2),fgts:+(l.x.fgts*l.fr).toFixed(2),va:+(l.x.va*l.fr).toFixed(2),total:+(l.x.total*l.fr).toFixed(2)})).filter(r=>r.obra_id);
  const p=periodo(d.k);await S.api.upsert('competencias',[{id:d.k,inicio:dk(p.ini),fim:dk(p.fim)}],'id');for(let i=0;i<rows.length;i+=300)await S.api.upsert('rateio_fechamento',rows.slice(i,i+300),'competencia_id,funcionario_id,obra_id');
  await S.api.update('competencias',{id:d.k},{status:'Fechada',fechada_por:S.user.id,fechada_em:new Date().toISOString()});toast('Competência '+compLabel(d.k)+' fechada. Total '+BRL(R.total));reload()},
 rReabrir:async()=>{if(!confirm('Reabrir a competência permite alterar o ponto do período e recalcular o rateio. Continuar?'))return;const d=D();await S.api.remove('rateio_fechamento',{eq:{competencia_id:d.k}});await S.api.update('competencias',{id:d.k},{status:'Aberta',fechada_por:null,fechada_em:null});await evento('Reabriu competência',d.k);reload()},
 rCsv:()=>{const d=D();const fech=d.cp&&d.cp.status==='Fechada';const R=fech&&d.snap.length?rateioSnap(d):calcRateio(d);const ob=R.porObra.filter(o=>o.total>0);
  csv('rateio_'+d.k+'.csv',[['CUSTO DE MÃO DE OBRA - '+perLabel(d.k)],['FUNCIONÁRIO','CUSTO TOTAL','TOTAL HT',...ob.flatMap(o=>[obraNome(o.obra)+' HORAS TRAB',obraNome(o.obra)+' VALOR'])],...R.pessoas.map(x=>[x.f.nome,N(x.total,2),N(x.ht/60,2),...ob.flatMap(o=>{const h=(x.horas[o.obra]||0)/60;return [h?N(h,2):'',h&&x.ht?N(x.total*(x.horas[o.obra]/x.ht),2):'']})]),[],
   ['SALÁRIOS','','',...ob.flatMap(o=>['',N(o.sal,2)])],['HORAS EXTRAS','','',...ob.flatMap(o=>['',N(o.he,2)])],...ENC.map(([x,l])=>[l.toUpperCase(),'','',...ob.flatMap(o=>['',N(o[x],2)])]),['VALE-ALIMENTAÇÃO','','',...ob.flatMap(o=>['',N(o.va,2)])],['CUSTO TOTAL DA OBRA','','',...ob.flatMap(o=>[N(o.horas/60,2),N(o.total,2)])]])}});

